        return 0
    if n == 0:
        return 1

    # For Jack: can jump 1, 2, or 3 stairs
    jack_ways = [0] * (n + 1)
    jack_ways[0] = 1

    for i in range(1, n + 1):
        jack_ways[i] = jack_ways[i-1]  # jump 1 step
        if i >= 2:
            jack_ways[i] += jack_ways[i-2]  # jump 2 steps
        if i >= 3:
            jack_ways[i] += jack_ways[i-3]  # jump 3 steps

    # For Jill: can jump 1 or 2 stairs
    jill_ways = [0] * (n + 1)
    jill_ways[0] = 1

    for i in range(1, n + 1):
        jill_ways[i] = jill_ways[i-1]  # jump 1 step
        if i >= 2:
            jill_ways[i] += jill_ways[i-2]  # jump 2 steps

    return jack_ways[n], jill_ways[n]

