def solve():
    n = int(input())
    arr = list(map(int, input().split()))

    # If less than 2 elements, no good subset exists
    if n < 2:
        return -1

    # Sort the array to help with divisibility checks
    arr.sort()

    # Function to check if a subset is good
    def is_good_subset(subset):
        for i in range(len(subset)):
            for j in range(i + 1, len(subset)):
                if subset[i] % subset[j] != 0 and subset[j] % subset[i] != 0:
                    return False
        return True

    # Try all possible subsets of size >= 2
    max_size = 2  # minimum good subset size is 2

    # Generate all subsets of size from 2 to n
    from itertools import combinations

    for size in range(2, n + 1):
        for subset in combinations(arr, size):
            if is_good_subset(subset):
                max_size = size
                break
        if max_size > 2:  # found a valid subset of size > 2
            break

    return max_size if max_size >= 2 else -1

print(solve())
