def solve():
    n = int(input())
    arr = list(map(int, input().split()))

    # If less than 2 elements, no good subset of size >= 2
    if n < 2:
        return -1

    # Try all possible subsets of size 2 or more
    # Since constraint is small (n <= 1000), we can use a smarter approach

    # Sort the array to help with divisibility checks
    arr.sort()

    # Helper function to check if a subset is "good"
    def is_good(subset):
        for i in range(len(subset)):
            for j in range(i + 1, len(subset)):
                if subset[i] % subset[j] != 0 and subset[j] % subset[i] != 0:
                    return False
        return True

    # Try all possible subsets of size >= 2
    max_size = -1

    # Generate all subsets of size >= 2
    from itertools import combinations

    for size in range(2, n + 1):
        for subset in combinations(arr, size):
            if is_good(subset):
                max_size = max(max_size, size)

    return max_size

